#!/usr/bin/env python3
"""Generate 12 kHz coefficients; no trigonometry on either RP2040 core."""
import math
from pathlib import Path

lines = [
    "// Generated by tools/generate_taraf.py.",
    "#pragma once",
    "#include <cstdint>",
    "namespace mtm::tables {",
    "inline constexpr int32_t taraf[49][60][3] = {",
]
for note in range(36, 85):
    f0 = 440 * 2 ** ((note - 69) / 12)
    lines.append("{")
    for i in range(12):
        # Keep the first four slots stable; spend the former ninth-harmonic
        # slot on a second harmonic without adding any audio-rate work.
        for j, harm in enumerate((1, 3, 5, 7, 2)):
            f = f0 * harm * math.sqrt(1 + 0.00004 * (harm * harm - 1))
            if f >= 6000:
                lines.append("{0,0,0},")
                continue
            tau = (3.6 - 0.08 * i) / (1 + 0.08 * (harm - 1))
            r = math.exp(-1 / (12000 * tau))
            fast = math.exp(-1 / (12000 * (0.12 + 0.045 * ((i + 2 * j) % 9))))
            omega = 2 * math.pi * f / 12000
            gain = (
                0.065
                * math.sqrt(1 - r)
                * (0.12, 0.55, 1, 1.15, 0.85)[j]
                * math.sin(omega)
            )
            vals = (
                round(262144 * r * math.cos(omega)),
                round(262144 * fast * math.cos(omega)),
                round(gain * 262144 * 8),
            )
            lines.append("{%d,%d,%d}," % vals)
    lines.append("},")
lines += ["};", "}"]
Path(__file__).resolve().parents[1].joinpath("dsp/taraf_table.hpp").write_text(
    "\n".join(lines) + "\n"
)
